import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"套餐、订单与兑换码","description":"","frontmatter":{},"headers":[],"relativePath":"admin/plans-orders.md","filePath":"admin/plans-orders.md","lastUpdated":1788621106000}`),a={name:`admin/plans-orders.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="套餐、订单与兑换码" tabindex="-1">套餐、订单与兑换码 <a class="header-anchor" href="#套餐、订单与兑换码" aria-label="Permalink to “套餐、订单与兑换码”">​</a></h1><h2 id="套餐配置" tabindex="-1">套餐配置 <a class="header-anchor" href="#套餐配置" aria-label="Permalink to “套餐配置”">​</a></h2><p>套餐可定义适用对象、价格、计费周期、邮箱数、企业域名数、存储和每日发信值。当前套餐没有独立的“成员人数”字段。修改已售套餐前，先确认现有订阅是沿用旧权益还是跟随新配置，避免用户权益意外变化。</p><p>后台套餐记录分为个人 <code>personal</code> 和企业 <code>business</code> 两种范围。“个人免费”是用户没有有效个人订阅时由系统等级与默认配额形成的基础层，不是第三种套餐范围。隐藏套餐只应停止新购买，不应破坏已有订阅的查询和权益。</p><p>每个套餐必须明确属于个人或企业范围。个人订阅绑定一个用户，企业订阅绑定一个组织；数据库不允许同一订阅或订单同时归两个所有者。</p><p>个人套餐的邮箱、存储和每日发信值会与用户当前系统等级配额一起计算有效权益；企业套餐的域名、企业邮箱、组织存储和组织每日发信值作用于对应组织。个人套餐的域名数固定为 <code>0</code>。企业每日发信由组织全部企业邮箱共享，填 <code>0</code> 表示不限；个人每日发信填 <code>0</code> 表示继续使用基础额度。企业发送不会占用受派成员的个人额度或能量。</p><p>“企业 / 支付设置”还控制创建组织最低系统等级、每个用户最多创建的组织数、欠费宽限天数、组织停用后的数据保留天数、共享域名用户超出免费发信额度后的每收件人能量成本，以及邮箱转让成本。保留期结束会删除已停用组织及其域名、邮箱和邮件；缩短前必须先核对并备份。</p><p>支付通道可分别配置 NodeLoc 能量、易支付和 BEpusdt。密钥留空会保留已保存值；启用前完成签名、金额、币种、回调幂等和补单验证。管理员还可以为指定用户手工开通或延长个人套餐、为指定组织开通或延长企业套餐；这类操作必须说明依据并检查审计记录。当前后台只提供取消个人订阅的操作，没有对应的企业订阅取消按钮。</p><h2 id="订单" tabindex="-1">订单 <a class="header-anchor" href="#订单" aria-label="Permalink to “订单”">​</a></h2><p>订单管理页用于核对编号、用户或组织、金额、支付方式、状态和交易号；原始支付回调不在该页面直接展示，需要结合受限服务端日志排查。处理异常订单时按以下顺序：</p><ol><li>核对服务端收到的支付回调与签名验证结果。</li><li>核对支付平台交易号、金额和币种。</li><li>查看钱包流水或订阅权益是否已写入。</li><li>通过幂等处理补偿，避免重复加款或重复开通。</li></ol><p>不要仅根据用户付款截图手工改成已支付。</p><p>NodeLoc 能量、易支付和 BEpusdt 都必须在服务端验证回调凭据、金额、币种、订单号和当前状态。回调重复到达时只能完成一次权益发放。</p><h2 id="钱包流水" tabindex="-1">钱包流水 <a class="header-anchor" href="#钱包流水" aria-label="Permalink to “钱包流水”">​</a></h2><p>余额变化应有对应流水，包含方向、金额、业务来源和关联编号。人工调整必须写明原因和操作人。总余额与流水不一致时先停止继续调整，保存现场并检查事务日志。</p><p>发信和邮箱转让产生的能量扣费会在业务事务中预留、结算或退款。不要直接改余额而跳过流水，否则后续无法判断真实权益。</p><h2 id="兑换码" tabindex="-1">兑换码 <a class="header-anchor" href="#兑换码" aria-label="Permalink to “兑换码”">​</a></h2><p>兑换码仅用于个人 Pro 套餐。创建时选择套餐、有效天数、有效期和总使用次数；同一用户对同一兑换码固定只能兑换一次。批量生成后按敏感凭据管理，泄露时立即停用未使用代码；兑换记录应能追溯到用户、时间和获得的套餐。</p><h2 id="退款与取消" tabindex="-1">退款与取消 <a class="header-anchor" href="#退款与取消" aria-label="Permalink to “退款与取消”">​</a></h2><p>当前后台没有完整的自动退款流程。确需退款时，要同时核对支付平台、订单、钱包或订阅，并保留人工处理记录；不能只修改界面状态，也不能重复返还余额或权益。</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};